}

function buildVoxels(){
  var group = new THREE.Group();
  var instGroups = {};
  for(var i=0;i<voxels.length;i++){
    var v = voxels[i];
    var key = v.c+'_'+v.s;
    if(!instGroups[key]) instGroups[key] = [];
    instGroups[key].push(v);
  }
  // merged via InstancedMesh per color+scale
  var dummy = new THREE.Object3D();
  for(var key in instGroups){
    var arr = instGroups[key];
    var parts = key.split('_');
    var color = parseInt(parts[0]), s = parseFloat(parts[1]);
    var im = new THREE.InstancedMesh(getGeo(s), getMat(color), arr.length);
    for(var j=0;j<arr.length;j++){
      var v = arr[j];
      dummy.position.set(v.x, v.y, v.z);
      dummy.updateMatrix();
      im.setMatrixAt(j, dummy.matrix);
    }
    im.castShadow = true;
    im.receiveShadow = true;
    group.add(im);
  }
  return group;
}

